using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Security.Cryptography;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
using System.Windows.Forms;
namespace Aster {
class UpdateFile {public string Name;public long Size;public string Sha256;}
class UpdateManifest {public int Schema;public string AppId,Version;public List<UpdateFile> Files;}
class UpdatePackage {public UpdateManifest Manifest;public string Prefix,PackageHash;public long Bytes;}
static class AsterUpdate {
 public const string CurrentVersion="1.4";
 const long MaxTotal=250L*1024*1024,MaxFile=64L*1024*1024;
 public static string Hash(Stream stream){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant();}
 static string FileHash(Stream stream,long expected){using(var sha=SHA256.Create()){byte[] buffer=new byte[65536];long total=0;int count;while((count=stream.Read(buffer,0,buffer.Length))>0){total+=count;if(total>expected)throw new InvalidDataException("Expanded file exceeds its declared size.");sha.TransformBlock(buffer,0,count,buffer,0);}if(total!=expected)throw new InvalidDataException("Expanded file size mismatch.");sha.TransformFinalBlock(new byte[0],0,0);return BitConverter.ToString(sha.Hash).Replace("-","").ToLowerInvariant();}}
 static string ManifestText(ZipArchiveEntry entry){using(var input=entry.Open())using(var memory=new MemoryStream()){byte[] buffer=new byte[8192];int count;while((count=input.Read(buffer,0,buffer.Length))>0){if(memory.Length+count>2*1024*1024)throw new InvalidDataException("Manifest too large.");memory.Write(buffer,0,count);}memory.Position=0;using(var reader=new StreamReader(memory))return reader.ReadToEnd();}}
 public static bool SafeName(string name){if(string.IsNullOrEmpty(name)||name.Length>240||name.Contains('\\')||name.StartsWith("/")||name.EndsWith("/"))return false;foreach(string part in name.Split('/')){if(part=="."||part==".."||part.Length==0||part.EndsWith(".")||part.EndsWith(" ")||!Regex.IsMatch(part,@"^[A-Za-z0-9_. -]+$"))return false;string stem=part.Split('.')[0].ToUpperInvariant();if(new[]{"CON","PRN","AUX","NUL","CONIN$","CONOUT$"}.Contains(stem)||Regex.IsMatch(stem,@"^(COM|LPT)[0-9]$"))return false;}return true;}
 static void NoLinks(string path){var item=new DirectoryInfo(Path.GetFullPath(path));while(item!=null){if(item.Exists&&(item.Attributes&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("Linked update folders are not supported.");item=item.Parent;}}
 static FileStream OpenPackage(string path){var file=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read);if(file.Length>MaxTotal){file.Dispose();throw new InvalidDataException("Update ZIP exceeds 250 MB.");}return file;}
 static UpdatePackage Read(ZipArchive zip,string hash){if(zip.Entries.Count>5000)throw new InvalidDataException("Too many ZIP entries.");var files=new Dictionary<string,ZipArchiveEntry>(StringComparer.OrdinalIgnoreCase);long total=0;foreach(var entry in zip.Entries){string name=entry.FullName;if(name.EndsWith("/")){if(!SafeName(name.TrimEnd('/')))throw new InvalidDataException("Unsafe ZIP directory.");continue;}if(!SafeName(name)||entry.Length>MaxFile||((entry.ExternalAttributes>>16)&0xF000)==0xA000)throw new InvalidDataException("Unsafe or oversized ZIP entry.");if(files.ContainsKey(name))throw new InvalidDataException("Duplicate ZIP paths.");files.Add(name,entry);total=checked(total+entry.Length);if(total>MaxTotal)throw new InvalidDataException("Expanded update exceeds 250 MB.");}
 var candidates=files.Where(p=>p.Key.Equals("release.json",StringComparison.OrdinalIgnoreCase)||p.Key.EndsWith("/release.json",StringComparison.OrdinalIgnoreCase)).ToArray();if(candidates.Length!=1)throw new InvalidDataException("This ZIP needs one Aster release.json manifest. Use an update-ready Aster package.");var manifestEntry=candidates[0].Value;if(manifestEntry.Length>2*1024*1024)throw new InvalidDataException("Manifest too large.");UpdateManifest manifest=new JavaScriptSerializer{MaxJsonLength=2*1024*1024}.Deserialize<UpdateManifest>(ManifestText(manifestEntry));Version version;if(manifest==null||manifest.Schema!=1||manifest.AppId!="aster.desktop"||!Version.TryParse(manifest.Version,out version)||version<=new Version(CurrentVersion)||manifest.Files==null||manifest.Files.Count==0||manifest.Files.Count>4999)throw new InvalidDataException("Not a compatible newer Aster release. Installed version: "+CurrentVersion+".");string prefix=candidates[0].Key.Substring(0,candidates[0].Key.Length-"release.json".Length);if(prefix.TrimEnd('/').Contains('/'))throw new InvalidDataException("Use a package with at most one enclosing folder.");var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var item in manifest.Files){if(item==null||!SafeName(item.Name)||item.Name.Equals("release.json",StringComparison.OrdinalIgnoreCase)||!names.Add(item.Name)||item.Size<0||item.Size>MaxFile||item.Sha256==null||!Regex.IsMatch(item.Sha256,@"^[a-fA-F0-9]{64}$"))throw new InvalidDataException("Invalid release file list.");ZipArchiveEntry entry;if(!files.TryGetValue(prefix+item.Name,out entry)||entry.Length!=item.Size)throw new InvalidDataException("Missing or mismatched update file: "+item.Name);using(var stream=entry.Open())if(!String.Equals(FileHash(stream,item.Size),item.Sha256,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("File integrity check failed: "+item.Name);}
 if(files.Count!=manifest.Files.Count+1)throw new InvalidDataException("ZIP contains files not listed in its manifest.");foreach(string required in new[]{"Aster.exe","runtime/python.exe","runtime/python312.zip","AirDefense/air_defense.py","Video/index.html","Microsoft.Web.WebView2.Core.dll","Microsoft.Web.WebView2.WinForms.dll","WebView2Loader.dll"})if(!names.Contains(required))throw new InvalidDataException("Incomplete Aster package: "+required);foreach(string name in names){string parent=name;while(parent.Contains('/')){parent=parent.Substring(0,parent.LastIndexOf('/'));if(names.Contains(parent))throw new InvalidDataException("Conflicting file and directory paths.");}}
 using(var exe=files[prefix+"Aster.exe"].Open())if(exe.ReadByte()!=77||exe.ReadByte()!=90)throw new InvalidDataException("Aster.exe is not a Windows executable.");return new UpdatePackage{Manifest=manifest,Prefix=prefix,PackageHash=hash,Bytes=total};}
 public static UpdatePackage Inspect(string path){using(var file=OpenPackage(path)){string hash=Hash(file);file.Position=0;using(var zip=new ZipArchive(file,ZipArchiveMode.Read))return Read(zip,hash);}}
 public static string Install(string path,string expectedHash,string baseFolder,string currentFolder){using(var file=OpenPackage(path)){string hash=Hash(file);if(!String.Equals(hash,expectedHash,StringComparison.Ordinal))throw new InvalidDataException("The ZIP changed after review. Select it again.");file.Position=0;using(var zip=new ZipArchive(file,ZipArchiveMode.Read)){var package=Read(zip,hash);NoLinks(baseFolder);Directory.CreateDirectory(baseFolder);string destination=Path.GetFullPath(Path.Combine(baseFolder,"Aster-"+new Version(package.Manifest.Version).ToString()+"-"+Guid.NewGuid().ToString("N")));string root=Path.GetFullPath(baseFolder).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;if(!destination.StartsWith(root,StringComparison.OrdinalIgnoreCase)||Directory.Exists(destination))throw new IOException("Invalid update destination.");Directory.CreateDirectory(destination);foreach(var item in package.Manifest.Files){if(item.Name.Equals("home-location.json",StringComparison.OrdinalIgnoreCase))continue;string target=Path.GetFullPath(Path.Combine(destination,item.Name.Replace('/',Path.DirectorySeparatorChar)));if(!target.StartsWith(destination+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Invalid extraction path.");Directory.CreateDirectory(Path.GetDirectoryName(target));using(var input=zip.Entries.Single(e=>String.Equals(e.FullName,package.Prefix+item.Name,StringComparison.OrdinalIgnoreCase)).Open())using(var output=new FileStream(target,FileMode.CreateNew,FileAccess.Write)){input.CopyTo(output);}}
 foreach(string name in new[]{"home-location.json","AirDefense/places.json"}){string source=Path.Combine(currentFolder,name.Replace('/',Path.DirectorySeparatorChar));if(!File.Exists(source))continue;NoLinks(Path.GetDirectoryName(source));if((File.GetAttributes(source)&FileAttributes.ReparsePoint)!=0||new FileInfo(source).Length>262144)throw new IOException("Cannot preserve the local location file safely.");string target=Path.Combine(destination,name.Replace('/',Path.DirectorySeparatorChar));Directory.CreateDirectory(Path.GetDirectoryName(target));File.Copy(source,target,true);}
 File.WriteAllText(Path.Combine(destination,"installed-version.txt"),package.Manifest.Version+Environment.NewLine+"Source ZIP SHA-256: "+hash);return destination;}}}
}
partial class MainWindow {
 string installedUpdateFolder;bool updateBusy,updateCloseHook;
 void BuildOfflineUpdates(){if(!updateCloseHook){updateCloseHook=true;FormClosing+=(s,e)=>{if(updateBusy){e.Cancel=true;MessageBox.Show(this,"Wait for the update check or installation to finish before closing Aster.");}};}if(updateBusy){var wait=new Button{Text="An update operation is in progress. Click to refresh.",Dock=DockStyle.Top,Height=50};wait.Click+=(s,e)=>Navigate("Update Aster");content.Controls.Add(wait);return;}sub.Text="Installed: Aster "+AsterUpdate.CurrentVersion+" · install a newer downloaded package";string selected=null,installed=installedUpdateFolder;UpdatePackage reviewed=null;var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(20)};content.Controls.Add(flow);flow.Controls.Add(new Label{Text="Update Aster",AutoSize=true,Font=new Font("Segoe UI",25,FontStyle.Bold)});flow.Controls.Add(new Label{Text="Choose a newer Aster ZIP to review and install. Your current copy stays intact.\r\nThere is no online update server connected yet. Updates use downloaded packages.",AutoSize=true,Margin=new Padding(0,16,0,20)});var choose=Button("Choose update ZIP…");var install=Button("Install reviewed update");install.Enabled=false;var launch=Button("Switch to updated Aster");launch.Enabled=installed!=null;flow.Controls.Add(choose);flow.Controls.Add(install);flow.Controls.Add(launch);var details=new TextBox{ReadOnly=true,Multiline=true,ScrollBars=ScrollBars.Vertical,Width=740,Height=230,Text="Current version: "+AsterUpdate.CurrentVersion+"\r\nChoose an update package to begin."};if(installed!=null)details.Text="Previously installed update ready to open:\r\n"+installed;flow.Controls.Add(details);flow.Controls.Add(new Label{Text="Packages must contain release.json with a newer version and file hashes.\r\nHashes detect damage, not publisher identity. Only install a package you trust.\r\nYour home preset, place dictionary and shared workspace settings are preserved.\r\nThe old folder remains available if you need to return to the previous version.",AutoSize=true,Margin=new Padding(0,16,0,0)});
 choose.Click+=async(s,e)=>{using(var dialog=new OpenFileDialog{Filter="Aster update package|*.zip",Title="Choose a newer Aster release"}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;selected=dialog.FileName;}reviewed=null;installed=null;install.Enabled=launch.Enabled=choose.Enabled=false;updateBusy=true;details.Text="Checking version, paths and file integrity…";try{var result=await Task.Run(()=>AsterUpdate.Inspect(selected));if(details.IsDisposed)return;reviewed=result;details.Text="Update version: "+result.Manifest.Version+"\r\nFiles: "+result.Manifest.Files.Count+"\r\nExpanded size: "+(result.Bytes/1048576.0).ToString("F1")+" MB\r\n\r\nSHA-256 of package:\r\n"+result.PackageHash+"\r\n\r\nReady for your review. Installation does not launch the package.";install.Enabled=true;}catch(Exception ex){if(!details.IsDisposed)details.Text="Package rejected: "+ex.Message;}finally{updateBusy=false;if(!choose.IsDisposed)choose.Enabled=true;}};
 install.Click+=async(s,e)=>{if(reviewed==null)return;if(MessageBox.Show(this,"Install Aster "+reviewed.Manifest.Version+" from this ZIP?\r\nFile hashes passed, but the publisher is not authenticated. Continue only if you trust this package.\r\nYour current program folder will remain intact.","Install update",MessageBoxButtons.OKCancel,MessageBoxIcon.Information)!=DialogResult.OK)return;install.Enabled=choose.Enabled=false;updateBusy=true;details.Text="Installing into a new version folder…";try{string path=selected,hash=reviewed.PackageHash;string destination=await Task.Run(()=>AsterUpdate.Install(path,hash,Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Aster","Versions"),AppDomain.CurrentDomain.BaseDirectory));installedUpdateFolder=destination;if(details.IsDisposed)return;installed=destination;details.Text="Installed successfully.\r\n"+destination+"\r\n\r\nSwitch to updated Aster when ready. Your existing save/stop prompts still apply.";launch.Enabled=true;}catch(Exception ex){if(!details.IsDisposed)details.Text="Update could not finish: "+ex.Message+"\r\nThe current version was not replaced. Any incomplete new folder is not launched.";}finally{updateBusy=false;if(!choose.IsDisposed)choose.Enabled=true;}};
 launch.Click+=(s,e)=>{if(installed==null)return;string exe=Path.Combine(installed,"Aster.exe");Close();if(!IsDisposed)return;try{Process.Start(new ProcessStartInfo(exe){UseShellExecute=true,WorkingDirectory=installed});}catch{MessageBox.Show("The updated app could not launch. Open Aster.exe in:\r\n"+installed,"Aster update");}};
 }
}
}
